MC.registerPack({"id":"nova","cards":[{"id":"28001a","name":"노바","en":"* Nova","type":"hero","enc":false,"unique":true,"hp":10,"atk":1,"thw":1,"def":2,"hs":5,"tr":["CHAMPION"],"traits":["챔피언"],"text":"<b>반응</b>: 당신이 노바의 기본 기능(저지, 공격, 방어) 중 하나를 사용한 후, 슈퍼노바 헬멧을 준비합니다."},{"id":"28001b","name":"샘 알렉산더","en":"* Sam Alexander","type":"alter","enc":false,"unique":true,"hp":10,"rec":3,"hs":6,"tr":["CIVILIAN"],"traits":["시민"],"text":"<b>일상 행동</b>: 아무 유형의 자원 1개를 소모 → 당신의 덱과 버린 더미에서 슈퍼노바 헬멧을 찾음. 그 카드를 당신의 손에 더함([wild] 자원을 사용해 이 능력의 비용을 지불했다면 대신 플레이 영역에 내려놓음)."},{"id":"28002","name":"미즈 마블","en":"* Ms. Marvel","type":"ally","enc":false,"sub":"카말라 칸","unique":true,"hp":3,"atk":1,"atkStar":true,"thw":1,"thwStar":true,"cost":3,"res":"R","cls":"Hero","tr":["CHAMPION","INHUMAN"],"traits":["챔피언","인휴먼"],"text":"<b>히어로 반응</b>: 당신이 이벤트를 플레이한 후, 미즈 마블을 소진하고 그녀에게 피해 1점을 입힘 → 그 이벤트를 당신의 버린 더미에서 당신의 손으로 되돌림."},{"id":"28003","name":"역장 투사","en":"Forcefield Projection","type":"event","enc":false,"unique":false,"cost":1,"res":"R","cls":"Hero","tr":["SUPERPOWER"],"traits":["슈퍼파워"],"text":"<b>히어로 난입</b>: 아군 캐릭터가 공격으로 피해를 입으려 할 때, 그 피해에서 3점을 방지합니다. [wild] 자원을 사용해 이 카드의 비용을 지불했다면, 적 하나에게 피해 3점을 입힙니다."},{"id":"28004","name":"광속 비행","en":"Lightspeed Flight","type":"event","enc":false,"unique":false,"cost":2,"res":"B","cls":"Hero","tr":["SUPERPOWER","THWART"],"traits":["슈퍼파워","저지"],"text":"이 카드의 비용을 지불하는 동안 생성되는 [wild] 자원의 수가 2배가 됩니다.\n<b>히어로 행동</b><i>(저지)</i>: 음모 하나에서 위협을 3만큼 제거합니다."},{"id":"28005","name":"막 쏘기","en":"Pot Shot","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Hero","tr":["ATTACK","SUPERPOWER"],"traits":["공격","슈퍼파워"],"text":"이 카드의 비용을 지불하는 동안 생성되는 [wild] 자원의 수가 2배가 됩니다.\n<b>히어로 행동</b><i>(공격)</i>: 적 하나에게 피해 4점을 입힙니다."},{"id":"28006","name":"노바 포스 해방","en":"Unleash Nova Force","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Hero","tr":["SUPERPOWER"],"traits":["슈퍼파워"],"text":"라운드마다 최대 1장.\n<b>히어로 행동</b>: 이번 라운드 끝까지, 노바가 적을 격파하거나 음모에서 마지막 위협을 제거할 때마다, 노바를 준비하고 카드 1장을 뽑습니다."},{"id":"28007","name":"월드마인드와의 연결","en":"Connection to the Worldmind","type":"resource","enc":false,"unique":false,"res":"G","cls":"Hero","tr":[],"traits":[],"text":"월드마인드와의 연결은 당신의 손 크기에 포함되지 않습니다."},{"id":"28008","name":"제시 알렉산더","en":"* Jesse Alexander","type":"support","enc":false,"unique":true,"cost":2,"res":"B","cls":"Hero","tr":["PERSONA"],"traits":["페르소나"],"text":"<b>일상 행동</b>: 제시 알렉산더를 소진 → 당신의 버린 더미에서 월드마인드와의 연결 1장을 당신의 덱에 섞어 넣음. 카드 1장을 뽑음."},{"id":"28009","name":"슈퍼노바 헬멧","en":"* Supernova Helmet","type":"upgrade","enc":false,"unique":true,"cost":1,"res":"B","cls":"Hero","tr":["ARMOR"],"traits":["갑옷"],"text":"노바는 [[공중]] 특성을 얻습니다.\n<b>히어로 자원</b>: 슈퍼노바 헬멧 소진 → [wild] 자원을 생성."},{"id":"28010","name":"로커스트","en":"* The Locust","type":"ally","enc":false,"sub":"페르난다 로드리게스","unique":true,"hp":2,"atk":1,"atkStar":true,"thw":1,"thwStar":true,"thwCons":2,"cost":2,"res":"Y","cls":"Aggression","tr":["CHAMPION"],"traits":["챔피언"],"text":"당신의 아이덴티티가 [[챔피언]] 특성을 가지고 있을 때만 플레이할 수 있습니다.\n<b>히어로 반응</b>: 로커스트가 플레이 영역에 들어온 후, 당신의 버린 더미에서 용맹(빨간색) 이벤트 1장을 당신의 손에 더합니다."},{"id":"28011","name":"적을 추적하다","en":"Chase Them Down","type":"event","enc":false,"unique":false,"cost":0,"res":"B","cls":"Aggression","tr":["THWART"],"traits":["저지"],"text":"<b>반응</b>(저지): 당신의 히어로가 공격하여 적 하나를 격파한 후, 음모 하나에서 위협을 2만큼 제거합니다.","link":"01052"},{"id":"28012","name":"되받아치기","en":"Pitchback","type":"event","enc":false,"unique":false,"cost":1,"res":"R","cls":"Aggression","tr":["AERIAL","ATTACK"],"traits":["공중","공격"],"text":"당신의 아이덴티티가 [[공중]] 특성을 가지고 있을 때만 플레이할 수 있습니다.\n<b>히어로 반응</b><i>(공격)</i>: 당신의 히어로가 공격한 후, 적 하나에게 피해 4점을 입힙니다."},{"id":"28013","name":"무자비","en":"No Quarter","type":"event","enc":false,"unique":false,"cost":2,"res":"B","req":"R","cls":"Aggression","tr":["ATTACK"],"traits":["공격"],"text":"요구 조건([physical]).\n<b>히어로 행동</b><i>(공격)</i>: 적 하나에게 피해 4점을 입힙니다. 이 공격으로 그 적에게 입힌 초과 피해 1점마다, 당신의 덱 맨 위에서 카드 1장을 버리고 이렇게 버려진 용맹(빨간색) 카드를 모두 당신의 손에 더합니다."},{"id":"28014","name":"하나씩","en":"One by One","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Aggression","tr":["ATTACK"],"traits":["공격"],"text":"<b>히어로 행동</b><i>(공격)</i>: 적 하나에게 피해 2점을 입힙니다. 이 공격으로 그 적이 격파되면, 적 하나에게 피해 2점을 입힙니다."},{"id":"28015","name":"용맹의 힘","en":"The Power of Aggression","type":"resource","enc":false,"unique":false,"res":"G","cls":"Aggression","tr":[],"maxDeck":2,"traits":[],"text":"덱마다 최대 2장.\n용맹<i>(빨간색)</i> 카드에 이 카드를 비용으로 지불하는 한, 이 카드가 생성하는 자원은 2배가 됩니다.","link":"01055"},{"id":"28016","name":"유려한 움직임","en":"Fluid Motion","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Aggression","tr":["SKILL"],"traits":["기술"],"text":"<b>히어로 반응</b>: 당신이 [[공격]] 이벤트를 플레이한 후, 이 카드를 소진 → 당신의 히어로는 이번 페이즈의 끝까지 공격 +1을 받음([[공격]] 이벤트마다 최대 1회)."},{"id":"28017","name":"연마된 기술","en":"Honed Technique","type":"upgrade","enc":false,"unique":false,"cost":3,"res":"B","req":"BB","cls":"Aggression","tr":["SKILL"],"maxPer":1,"traits":["기술"],"text":"요구 조건([mental][mental]). 플레이어마다 최대 1장.\n<b>난입</b>: 당신이 용맹 [[공격]] 이벤트를 플레이할 때, [mental] 자원을 사용해 그 이벤트의 비용을 지불했다면, 그 이벤트가 입히는 피해를 그 이벤트에 인쇄된 자원 비용만큼 증가시킵니다."},{"id":"28018","name":"문 걸","en":"* Moon Girl","type":"ally","enc":false,"sub":"루넬라 라파예트","unique":true,"hp":3,"atk":2,"atkStar":true,"atkCons":2,"thw":2,"thwStar":true,"thwCons":2,"cost":3,"res":"B","cls":"Basic","tr":["CHAMPION","GENIUS"],"traits":["챔피언","천재"],"text":"당신의 아이덴티티가 [[챔피언]] 또는 [[천재]] 특성을 가지고 있을 때만 플레이할 수 있습니다.\n<b>반응</b>: 당신이 손에서 문 걸을 플레이한 후, 그녀의 비용을 지불하는 데 사용한 [mental] 자원마다 카드 1장을 뽑습니다."},{"id":"28019","name":"일상의 영웅","en":"Everyday Hero","type":"resource","enc":false,"unique":false,"res":"G","cls":"Basic","tr":[],"traits":[],"text":"당신의 아이덴티티가 [[시민]] 특성을 가지고 있는 한, 이 카드는 아무 플레이어를 위해 소모할 수 있으며 다음 텍스트를 얻습니다: \"<b>반응</b>: 당신이 플레이어를 위해 이 카드를 소모한 후, 그 플레이어의 아이덴티티가 입은 피해 1점을 치료합니다.\""},{"id":"28020","name":"챔피언스 이동식 벙커","en":"* Champions Mobile Bunker","type":"support","enc":false,"unique":true,"cost":2,"res":"R","cls":"Basic","tr":["CHAMPION","VEHICLE"],"traits":["챔피언","탈것"],"text":"<b>히어로 행동</b>: 챔피언스 이동식 벙커를 소진 → [[챔피언]] 특성을 가진 아이덴티티 하나를 선택. 그 아이덴티티를 조종하는 플레이어는 카드 2장을 뽑은 후 자신의 손에서 카드 2장을 버려도 됨."},{"id":"28021","name":"세상의 무게","en":"Weight of the World","type":"obligation","enc":true,"set":"Nova","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>샘 알렉산더 플레이어에게 이 카드를 줍니다.</b>\n이 카드가 플레이 영역에 있는 한, 슈퍼노바 헬멧은 준비될 수 없습니다.\n<b>일상 행동</b>: 샘 알렉산더를 소진 → 이 의무 카드를 게임에서 제거."},{"id":"28022","name":"\"전쟁을 가져와라!\"","en":"\"Bring the War!\"","type":"side","enc":true,"set":"Nova Nemesis","unique":false,"boost":2,"start":2,"hazard":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 각 플레이어는 자신이 조종하는 카드 중 [wild] 자원이 인쇄된 카드 1장을 버립니다. 이렇게 버려진 카드마다 이 카드에 위협을 1만큼 놓습니다."},{"id":"28023","name":"워브링어","en":"* Warbringer","type":"minion","enc":true,"set":"Nova Nemesis","unique":true,"hp":5,"atk":3,"sch":1,"boost":3,"tr":["BRUTE","CHITAURI"],"nemesis":true,"traits":["야만","치타우리"],"text":"[star] <b>강제 난입</b>: 워브링어가 당신을 공격할 때, 당신의 손에 있는 [wild] 자원이 인쇄된 카드마다 그는 그 공격 동안 공격 +1을 받습니다. 그 공격은 압살을 얻습니다.\n<i>(노바의 숙적 하수인.)</i>","star":true},{"id":"28024","name":"전쟁 배달","en":"War Delivery","type":"treachery","enc":true,"set":"Nova Nemesis","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 당신은 [wild] 자원 1개를 소모해도 됩니다. 그렇게 하지 않으면, 빌런과 워브링어가 각각 당신을 공격합니다 <i>(당신이 일상 형태여도)</i>.\n<hr />\n[star] <b>강화</b>: 당신의 손에 있는 [wild] 자원이 인쇄된 카드마다 주요 음모에 위협을 1만큼 놓습니다.","star":true,"boostStar":true},{"id":"28025","name":"\"전쟁은 이미 시작됐다\"","en":"\"The War's Been Brought\"","type":"treachery","enc":true,"set":"Nova Nemesis","unique":false,"surge":1,"tr":[],"traits":[],"text":"쇄도.\n<b>공개될 때</b>: 조우 덱 맨 위에서 카드 X장을 버립니다. X는 당신의 손에 있는 카드, 당신이 조종하는 카드, 당신의 버린 더미에 있는 카드에 인쇄된 [wild] 자원의 총 개수와 같습니다."},{"id":"28026","name":"요잉과 롤링","en":"Yaw and Roll","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Justice","tr":["AERIAL","THWART"],"traits":["공중","저지"],"text":"당신의 아이덴티티가 [[공중]] 특성을 가지고 있을 때만 플레이할 수 있습니다.\n<b>히어로 반응</b><i>(저지)</i>: 당신의 히어로가 저지한 후, 음모 하나에서 위협을 3만큼 제거합니다."},{"id":"28027","name":"고지대의 이점","en":"Height Advantage","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"B","cls":"Protection","tr":["AERIAL","TACTIC"],"traits":["공중","전술"],"text":"당신의 아이덴티티가 [[공중]] 특성을 가지고 있는 한, 각 적의 공격으로 당신이 입는 피해가 1 감소합니다.\n<b>강제 난입</b>: 당신의 차례가 시작될 때, 이 카드를 버립니다."},{"id":"28028","name":"기갑 강습","en":"Armored Assault","type":"side","enc":true,"set":"Armadillo","unique":false,"boost":2,"start":3,"startStar":true,"tr":[],"traits":[],"text":"강인함 상태 카드가 있는 각 적은 공격 +3을 받습니다."},{"id":"28029","name":"아르마딜로","en":"* Armadillo","type":"minion","enc":true,"set":"Armadillo","unique":true,"hp":8,"atk":2,"sch":1,"boost":3,"tr":["BRUTE","ELITE"],"toughness":1,"traits":["야만","간부"],"text":"강인.\n아르마딜로는 강인함 상태 카드를 개수 제한 없이 가질 수 있습니다.\n[star] <b>강제 반응</b>: 아르마딜로가 당신을 상대로 활성화한 후, 그에게 강인함 상태 카드를 줍니다.","star":true},{"id":"28030","name":"굴러, 굴러","en":"Rollin', Rollin'","type":"attachment","enc":true,"set":"Armadillo","unique":false,"boost":2,"plus":{"atk":2},"tr":["CONDITION"],"traits":["상태"],"text":"아르마딜로에게 장착합니다. 아르마딜로가 플레이 영역에 없다면, 조우 덱과 버린 조우 더미에서 아르마딜로를 찾아 당신과 교전 중인 채로 플레이 영역에 내려놓고 이 카드를 그에게 장착합니다. <i>(덱을 섞습니다.)</i>\n[star] 아르마딜로에게 강인함 상태 카드가 있는 한, 캐릭터는 그의 공격을 방어할 수 없습니다.","star":true},{"id":"28031","name":"거칠고 험하게","en":"Tough and Tumble","type":"treachery","enc":true,"set":"Armadillo","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때 (일상)</b>: 강인함 상태 카드가 있는 각 적이 암약합니다. 이렇게 활성화한 적이 없다면, 이 카드는 쇄도를 얻습니다.\n<b>공개될 때 (히어로)</b>: 강인함 상태 카드가 있는 각 적이 당신을 공격합니다. 이렇게 활성화한 적이 없다면, 이 카드는 쇄도를 얻습니다."},{"id":"28032","name":"참고 버티기","en":"Tough It Out","type":"treachery","enc":true,"set":"Armadillo","unique":false,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 아르마딜로와 빌런에게 각각 강인함 상태 카드를 줍니다. 이렇게 준 강인함 상태 카드가 1장 이하라면, 이 카드는 쇄도를 얻습니다."}]});
